import json

# Keep only cells that are part of a larger connected component (size >= 2)
# Or more precisely: remove truly isolated (single-cell) components

def find_components_size(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    visited = set()
    components = {}  # key: cell value, val: list of positions

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and (r,c) not in visited:
                color = grid[r][c]
                comp = [(r,c)]
                stack = [(r,c)]
                while stack:
                    curr_r, curr_c = stack.pop()
                    if (curr_r, curr_c) in visited or grid[curr_r][curr_c] != color:
                        continue
                    visited.add((curr_r, curr_c))
                    comp.append((curr_r, curr_c))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color:
                            stack.append((nr, nc))

                components[color] = comp
    return components

components = find_components_size(input_grid)
print("Component sizes by color:")
for color, comp in sorted(components.items()):
    print(f"  Color {color}: {len(comp)} cells")

# Keep only components with size >= 2
